// Enum for different types of accounts
type AccountType int32

const (
	// Asset Accounts
	AccountType_ASSET                    AccountType = 0 // General asset account (current, fixed, intangible)
	AccountType_CASH                     AccountType = 1 // Cash or cash equivalents
	AccountType_BANK                     AccountType = 2 // Bank accounts (Cash in banks)
	AccountType_RECEIVABLE               AccountType = 3 // Amounts owed by customers
	AccountType_INVENTORY                AccountType = 4 // Goods held for resale
	AccountType_PREPAID_EXPENSES         AccountType = 5 // Expenses paid in advance
	AccountType_PROPERTY_PLANT_EQUIPMENT AccountType = 6 // Physical fixed assets (PP&E)
	// Liability Accounts
	AccountType_LIABILITY        AccountType = 7  // General liability account (current, long-term)
	AccountType_PAYABLE          AccountType = 8  // Amounts owed to suppliers
	AccountType_UNEARNED_REVENUE AccountType = 9  // Income received but not yet earned
	AccountType_LOAN_PAYABLE     AccountType = 10 // Loan obligations
	// Equity Accounts
	AccountType_EQUITY            AccountType = 11 // Owner’s equity (capital)
	AccountType_COMMON_STOCK      AccountType = 12 // Equity from common stock issued
	AccountType_RETAINED_EARNINGS AccountType = 13 // Accumulated profits
	AccountType_DIVIDENDS_PAID    AccountType = 14 // Dividends issued to shareholders
	// Revenue Accounts
	AccountType_REVENUE         AccountType = 15 // General revenue (sales)
	AccountType_SALES_REVENUE   AccountType = 16 // Revenue from product or service sales
	AccountType_SERVICE_REVENUE AccountType = 17 // Revenue from services provided
	AccountType_OTHER_REVENUE   AccountType = 18 // Non-primary revenue (e.g., interest)
	// Expense Accounts
	AccountType_EXPENSE              AccountType = 19 // General expense account
	AccountType_COST_OF_GOODS_SOLD   AccountType = 20 // Direct costs of goods or services sold
	AccountType_STOCK_ADJUSTMENT     AccountType = 21 // Stock adjustment (inventory corrections, etc.)
	AccountType_OPERATING_EXPENSES   AccountType = 22 // Operating costs (rent, salaries, etc.)
	AccountType_DEPRECIATION_EXPENSE AccountType = 23 // Depreciation of assets
	AccountType_INTEREST_EXPENSE     AccountType = 24 // Interest payments
	AccountType_TAX_EXPENSE          AccountType = 25 // Taxes paid
	// Contra Accounts
	AccountType_ACCUMULATED_DEPRECIATION        AccountType = 26 // Depreciation accumulated on assets
	AccountType_ALLOWANCE_FOR_DOUBTFUL_ACCOUNTS AccountType = 27 // Estimate of uncollectible receivables
	AccountType_SALES_DISCOUNTS                 AccountType = 28 // Discounts offered on sales
	AccountType_SALES_RETURNS_AND_ALLOWANCES    AccountType = 29 // Returns and allowances granted to customers
	// Other specific types
	AccountType_ASSET_RECEIVED_BUT_NOT_BILLED AccountType = 30 // Asset received but not yet invoiced
	AccountType_OTHER_ASSET                   AccountType = 31 // Miscellaneous or intangible assets
	AccountType_OTHER_LIABILITY               AccountType = 32 // Miscellaneous liabilities
)

